// EDIT RULES: do not edit this file; regenerating replaces all of it. The menu is menu/menu.mjs; your own commands go in a file of your own.
// What the suite's menu (crew) and its jira command ask a person at a terminal: a choice from a list
// (arrows or a number, Enter; Space ticks one of several where several may be chosen), or a line typed
// (a token typed shown as dots). Esc leaves: null, or an empty answer.
import { emitKeypressEvents } from 'node:readline';

const color = Boolean(process.stdout.isTTY) && !process.env.NO_COLOR;
const paint = (code) => (s) => (color ? `\x1b[${code}m${s}\x1b[0m` : s);
export const bold = paint('1');
export const dim = paint('2');
export const cyan = paint('36');
/** True for a person at a terminal: only then is anything asked. */
export const tty = Boolean(process.stdin.isTTY && process.stdout.isTTY);

const KEYS = { up: -1, k: -1, down: 1, j: 1, tab: 1 };

/** Raw keys from the terminal until `onKey` says done; then the terminal as it was. */
function keys(onKey) {
  return new Promise((done) => {
    const finish = (value) => {
      process.stdin.off('keypress', handle);
      process.stdin.setRawMode(false);
      process.stdin.pause();
      done(value);
    };
    const handle = (typed, key = {}) => onKey(typed, key, finish);
    emitKeypressEvents(process.stdin);
    process.stdin.setRawMode(true);
    process.stdin.on('keypress', handle);
    process.stdin.resume();
  });
}

/**
 * One choice from a list of { label, what }, drawn in place: its index, or null on Esc. `multi`: Space
 * ticks or unticks each, Enter takes the ticked (the highlighted one when none is): a list of indexes.
 * `ticked`: the indexes ticked at the start; `at`: the one highlighted.
 */
export function choose(list, { multi = false, ticked = [], at = 0, esc = 'to leave' } = {}) {
  const on = new Set(ticked);
  let digits = '';
  let drawn = 0;
  const draw = () => {
    if (drawn) process.stdout.write(`\x1b[${drawn}A\x1b[0J`);
    const box = (i) => (multi ? `${on.has(i) ? '[x]' : '[ ]'} ` : '');
    const lines = [
      ...list.map((c, i) => (i === at ? `  ${cyan('›')} ${bold(`${box(i)}${i + 1}  ${c.label}`)}` : `    ${box(i)}${i + 1}  ${c.label}`)),
      '',
      ...(list[at].what ? [`  ${dim(list[at].what)}`] : []),
      `  ${dim(multi ? `↑ ↓ to move, Space to tick, Enter when done, Esc ${esc}` : `↑ ↓ to move, Enter to do it, Esc ${esc}`)}`,
    ];
    process.stdout.write(`${lines.join('\n')}\n`);
    drawn = lines.length;
  };
  draw();
  return keys((_, key, finish) => {
    if (key.name === 'escape' || (!multi && key.name === 'q') || (key.ctrl && key.name === 'c')) return finish(null);
    if (key.name === 'return' || key.name === 'enter') return finish(multi ? (on.size ? [...on].sort((a, b) => a - b) : [at]) : at);
    if (multi && key.name === 'space') {
      if (on.has(at)) on.delete(at);
      else on.add(at);
      return draw();
    }
    if (key.name in KEYS) {
      at = (at + KEYS[key.name] + list.length) % list.length;
      digits = '';
      return draw();
    }
    if (!/^[0-9]$/.test(key.sequence ?? '')) return;
    const fits = (t) => Number(t) >= 1 && Number(t) <= list.length;
    const typed = fits(digits + key.sequence) ? digits + key.sequence : fits(key.sequence) ? key.sequence : '';
    if (!typed) return;
    at = Number(typed) - 1;
    digits = Number(typed) * 10 > list.length ? '' : typed;
    if (!multi && !digits) return finish(at);
    draw();
  });
}

/** One line typed: Enter with nothing typed waits, Esc gives ''. `hidden`: each character shown as a dot (a token). */
export function ask(question, { hidden = false } = {}) {
  let text = '';
  process.stdout.write(`  ${question}\n  ${dim('(Esc to stop)')}\n  › `);
  return keys((typed, key, finish) => {
    const end = (answer) => {
      process.stdout.write('\n');
      finish(answer);
    };
    if (key.name === 'escape' || (key.ctrl && key.name === 'c')) return end('');
    if (key.name === 'return' || key.name === 'enter') return text.trim() ? end(text.trim()) : undefined;
    if (key.name === 'backspace') {
      if (text) process.stdout.write('\b \b');
      text = text.slice(0, -1);
      return;
    }
    if (typed && !key.ctrl && /^[\x20-\x7e]+$/.test(typed)) {
      text += typed;
      process.stdout.write(hidden ? '•'.repeat(typed.length) : typed);
    }
  });
}
